UNIT_SECONDS = {"s": 1, "m": 60, "h": 3600}

def parse_duration(text):
    match = re.fullmatch(r"(\d+)([smh])", text.strip())
    if not match:
        raise ValueError("bad duration: %s" % text)
    value, unit = match.groups()
    return int(value) * UNIT_SECONDS[unit]

