def score_to_point(score):
    # 分段映射：90+ 4.0，80+ 3.0，70+ 2.0，60+ 1.0，其余 0
    if score >= 90:
        return 4.0
    if score >= 80:
        return 3.0
    if score >= 70:
        return 2.0
    if score >= 60:
        return 1.0
    return 0.0


def calc_gpa(scores):
    # scores 是百分制成绩列表；空列表返回 0
    if not scores:
        return 0.0
    total = sum(score_to_point(s) for s in scores)
    return total / len(scores)

