function normalizeName(raw) {
  // 去掉首尾空白并折叠中间连续空白
  const cleaned = String(raw).trim().replace(/\s+/g, ' ');
  if (!cleaned) {
    return '';
  }
  // 每个词首字母大写
  return cleaned.split(' ').map(function (word) {
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  }).join(' ');
}

