async function retryCall(fn, times, delayMs) {
  let lastError = null;
  for (let attempt = 0; attempt < times; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      await new Promise(function (resolve) {
        setTimeout(resolve, delayMs * (attempt + 1));
      });
    }
  }
  throw lastError;
}

