def tokenize(text):
    return re.findall(r"[\w']+", text.lower())


def count_words(tokens):
    counts = {}
    for token in tokens:
        counts[token] = counts.get(token, 0) + 1
    return counts


def top_n(counts, n):
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ranked[:n]


def pipeline(text, n=5):
    return top_n(count_words(tokenize(text)), n)

